                    "reasoning" => {
                        if let Some(text) = part_text(part) {
                            if !text.is_empty() {
                                batch.push(HistoryMessage {
                                    id: part_id,
                                    role: "assistant".to_string(),
                                    content: format!("> {text}"),
                                    tool_name: None,
                                    turn_id: Some(message_id.clone()),
                                    timestamp: part_time,
                                });
