                            continue;
                        }
                        if let Some(obj) = state.as_object() {
                            if obj.is_empty() {
                                continue;
                            }
                        }
                        let tool_name = part["tool"]
                            .as_str()
                            .or_else(|| part["name"].as_str())
                            .unwrap_or("tool")
                            .to_string();
                        let content = serde_json::to_string_pretty(&state)
