                            id: part_id,
                            role: "tool".to_string(),
                            content,
                            tool_name: Some(tool_name),
                            turn_id: Some(message_id.clone()),
                            timestamp: part_time,
                        });
                    }
                    _ => {}
                }
            }

            normalize_planning_message_order(&mut batch);
            messages.extend(batch);
        }
    }

    Ok(messages)
