18: async fn opencode_resolve_service_url(
19:     state: &State<'_, Mutex<OpencodeState>>,
20: ) -> Result<String, String> {
21:     let cached = {
22:         let guard = state.lock().map_err(|e| e.to_string())?;
23:         guard.base_url.clone()
24:     };
25:     if let Some(url) = cached {
26:         return Ok(url);
27:     }
28: 
29:     let url = opencode_base_url();
30:     let client = reqwest::Client::new();
31:     if !opencode_is_healthy(&client, &url).await {
32:         return Err("OpenCode server is not running".to_string());
33:     }
34: 
35:     let mut guard = state.lock().map_err(|e| e.to_string())?;
36:     if guard.base_url.is_none() {
37:         guard.base_url = Some(url.clone());
38:     }
39:     Ok(url)
40: }
