395: fn parse_opencode_sse_payload(line: &str) -> Option<&str> {
396:     let trimmed = line.trim();
397:     if trimmed.is_empty() || trimmed.starts_with(':') {
398:         return None;
399:     }
400:     if let Some(data) = trimmed.strip_prefix("data:") {
401:         let payload = data.trim();
402:         if payload.is_empty() || payload == "[DONE]" {
403:             return None;
404:         }
405:         return Some(payload);
406:     }
407:     if trimmed.starts_with('{') || trimmed.starts_with('[') {
408:         return Some(trimmed);
409:     }
410:     None
411: }
