413: #[tauri::command]
414: pub async fn opencode_subscribe_events(
415:     thread_id: String,
416:     app: AppHandle,
417:     state: State<'_, Mutex<OpencodeState>>,
418: ) -> Result<(), String> {
419:     let (url, listening, subscribed_session_id, sse_task_active, sse_reconnect) = {
420:         let guard = state.lock().map_err(|e| e.to_string())?;
421:         let url = guard
422:             .base_url
423:             .clone()
424:             .unwrap_or_else(opencode_base_url);
425:         *guard
426:             .subscribed_session_id
427:             .lock()
428:             .map_err(|e| e.to_string())? = Some(thread_id);
429:         guard.listening.store(true, std::sync::atomic::Ordering::SeqCst);
430:         guard
431:             .sse_reconnect
432:             .store(true, std::sync::atomic::Ordering::SeqCst);
433:         (
434:             url,
435:             guard.listening.clone(),
436:             guard.subscribed_session_id.clone(),
437:             guard.sse_task_active.clone(),
438:             guard.sse_reconnect.clone(),
439:         )
440:     };
441: 
442:     if sse_task_active.load(std::sync::atomic::Ordering::SeqCst) {
443:         return Ok(());
444:     }
445: 
446:     sse_task_active.store(true, std::sync::atomic::Ordering::SeqCst);
447: 
448:     tokio::spawn(async move {
449:         let client = reqwest::Client::new();
450:         let events_url = format!("{url}/event");
451: 
452:         while listening.load(std::sync::atomic::Ordering::SeqCst) {
453:             let response = match client.get(&events_url).send().await {
454:                 Ok(response) => response,
455:                 Err(error) => {
456:                     let _ = app.emit(
457:                         "agent-error",
458:                         serde_json::json!({
459:                             "providerId": "opencode",
460:                             "message": format!("SSE connect failed: {error}"),
461:                         }),
462:                     );
463:                     tokio::time::sleep(std::time::Duration::from_millis(1200)).await;
464:                     continue;
465:                 }
466:             };
467: 
468:             let mut stream = response.bytes_stream();
469:             let mut buffer = String::new();
470: 
471:             loop {
472:                 if !listening.load(std::sync::atomic::Ordering::SeqCst) {
473:                     break;
474:                 }
475:                 if sse_reconnect.swap(false, std::sync::atomic::Ordering::SeqCst) {
476:                     break;
477:                 }
478: 
479:                 match tokio::time::timeout(
480:                     std::time::Duration::from_millis(400),
481:                     stream.next(),
482:                 )
483:                 .await
484:                 {
485:                     Ok(Some(Ok(chunk))) => {
486:                         buffer.push_str(&String::from_utf8_lossy(&chunk));
487: 
488:                         while let Some(pos) = buffer.find("\n\n") {
489:                             let block = buffer[..pos].to_string();
490:                             buffer = buffer[pos + 2..].to_string();
491: 
492:                             let session_id = subscribed_session_id
493:                                 .lock()
494:                                 .ok()
495:                                 .and_then(|guard| guard.clone())
496:                                 .unwrap_or_default();
497: 
498:                             if session_id.is_empty() {
499:                                 continue;
500:                             }
501: 
502:                             for line in block.lines() {
503:                                 let Some(data) = parse_opencode_sse_payload(line) else {
504:                                     continue;
505:                                 };
506:                                 if let Ok(event) =
507:                                     serde_json::from_str::<serde_json::Value>(data)
508:                                 {
509:                                     if let Some(normalized) =
510:                                         opencode_normalize_event(&event, &session_id)
511:                                     {
512:                                         let payload = serde_json::json!({
513:                                             "providerId": "opencode",
514:                                             "event": normalized,
515:                                         });
516:                                         let _ = app.emit("agent-event", payload);
517:                                     }
518:                                 }
519:                             }
520:                         }
521:                     }
522:                     Ok(Some(Err(error))) => {
523:                         let _ = app.emit(
524:                             "agent-error",
525:                             serde_json::json!({
526:                                 "providerId": "opencode",
527:                                 "message": format!("SSE stream error: {error}"),
528:                             }),
529:                         );
530:                         break;
531:                     }
532:                     Ok(None) => break,
533:                     Err(_) => continue,
534:                 }
535:             }
536: 
537:             if listening.load(std::sync::atomic::Ordering::SeqCst) {
538:                 tokio::time::sleep(std::time::Duration::from_millis(800)).await;
539:             }
540:         }
541: 
542:         sse_task_active.store(false, std::sync::atomic::Ordering::SeqCst);
543:     });
544: 
545:     Ok(())
546: }
