    let connection = open_database()?;
    connection
        .execute(
            "UPDATE project SET worktree = ?1, vcs = ?2, time_updated = ?3 WHERE id = 'global'",
            params![backup.worktree, backup.vcs, backup.time_updated],
        )
        .map_err(|error| format!("恢复 global 项目失败：{error}"))?;
    Ok(())
}
